import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    # deadline with safety margin
    deadline = t0 + budget_seconds * 0.85

    # --- initial configuration: hex-ish arrangement with radius scaled to fit ---
    best = None
    best_score = -1.0

    def score(cfg):
        return cfg[:, 2].sum()

    def repair(cfg):
        cfg = cfg.copy()
        # clamp into box
        for i in range(n):
            r = cfg[i, 2]
            cfg[i, 0] = min(max(cfg[i, 0], r), 1.0 - r)
            cfg[i, 1] = min(max(cfg[i, 1], r), 1.0 - r)
        return cfg

    def overlap_push(cfg, iters=50):
        # simple relaxation to remove overlaps, then shrink if needed
        cfg = cfg.copy()
        for _ in range(iters):
            moved = False
            for i in range(n):
                xi, yi, ri = cfg[i]
                for j in range(i + 1, n):
                    xj, yj, rj = cfg[j]
                    dx = xj - xi
                    dy = yj - yi
                    d = np.hypot(dx, dy)
                    s = ri + rj
                    if d < s and d > 1e-12:
                        push = (s - d) * 0.5 + 1e-9
                        ux, uy = dx / d, dy / d
                        xi -= ux * push
                        yi -= uy * push
                        xj += ux * push
                        yj += uy * push
                        cfg[i, 0], cfg[i, 1] = xi, yi
                        cfg[j, 0], cfg[j, 1] = xj, yj
                        moved = True
            cfg = repair(cfg)
            if not moved:
                break
        return cfg

    def max_scale(cfg):
        # given centers, find max common radius multiplier so all fit
        # we treat cfg[:,2] as relative sizes; scale up until first violation
        # solve: scale s such that all constraints hold, then return cfg with r*s
        # Use binary search on s.
        base = cfg[:, 2].copy()
        if base.max() <= 0:
            return cfg
        lo, hi = 0.0, 1.0
        # find upper bound
        while True:
            r = base * hi
            ok = True
            for i in range(n):
                if r[i] > 0.5 + 1e-12:
                    ok = False
                    break
            if ok:
                for i in range(n):
                    for j in range(i + 1, n):
                        d = np.hypot(cfg[i, 0] - cfg[j, 0], cfg[i, 1] - cfg[j, 1])
                        if d < r[i] + r[j] - 1e-12:
                            ok = False
                            break
                    if not ok:
                        break
            if not ok:
                break
            hi *= 2.0
            if hi > 1e6:
                break
        for _ in range(60):
            mid = 0.5 * (lo + hi)
            r = base * mid
            ok = True
            for i in range(n):
                if r[i] > 0.5 + 1e-12:
                    ok = False
                    break
            if ok:
                for i in range(n):
                    for j in range(i + 1, n):
                        d = np.hypot(cfg[i, 0] - cfg[j, 0], cfg[i, 1] - cfg[j, 1])
                        if d < r[i] + r[j] - 1e-12:
                            ok = False
                            break
                    if not ok:
                        break
            if ok:
                lo = mid
            else:
                hi = mid
        out = cfg.copy()
        out[:, 2] = base * lo
        return repair(out)

    # build candidates
    def hex_init(rows=6):
        pts = []
        r0 = 0.5 / 6.0
        for j in range(rows):
            y = (j + 0.5) * (1.0 / rows)
            offset = 0.5 * (1.0 / rows) if (j % 2) else 0.0
            cols = 6
            for i in range(cols):
                x = (i + 0.5) / cols + offset
                if 0 <= x <= 1:
                    pts.append((x, y, 1.0))
        pts = pts[:n]
        while len(pts) < n:
            pts.append((0.5, 0.5, 1.0))
        return np.array(pts, dtype=float)

    candidates = []
    # Candidate A: hex
    candidates.append(hex_init())
    # Candidate B: start
    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        if s.shape == (n, 3):
            s = repair(s)
            candidates.append(s)
    # Candidate C: random jittered grid
    rng = np.random.default_rng(12345)
    for _ in range(3):
        c = hex_init()
        c[:, 0] += rng.uniform(-0.03, 0.03, n)
        c[:, 1] += rng.uniform(-0.03, 0.03, n)
        c = repair(c)
        candidates.append(c)

    for c in candidates:
        c = repair(c)
        c = overlap_push(c, iters=80)
        c = max_scale(c)
        sc = score(c)
        if sc > best_score:
            best_score = sc
            best = c.copy()

    # --- local optimization: try to grow each radius greedily while keeping feasibility ---
    def feasible(cfg):
        for i in range(n):
            r = cfg[i, 2]
            if r <= 0:
                return False
            if cfg[i, 0] - r < -1e-12 or cfg[i, 0] + r > 1 + 1e-12:
                return False
            if cfg[i, 1] - r < -1e-12 or cfg[i, 1] + r > 1 + 1e-12:
                return False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(cfg[i, 0] - cfg[j, 0], cfg[i, 1] - cfg[j, 1])
                if d < cfg[i, 2] + cfg[j, 2] - 1e-12:
                    return False
        return True

    def try_grow(cfg, idx, step):
        c = cfg.copy()
        c[idx, 2] += step
        if feasible(c):
            return c, True
        return cfg, False

    # coordinate ascent on radii + small position tweaks
    cfg = best.copy()
    step = 0.01
    while time.process_time() < deadline:
        improved = False
        order = list(range(n))
        np.random.shuffle(order)
        for i in order:
            if time.process_time() >= deadline:
                break
            # try growing radius
            for s in (step, step * 0.5, step * 0.2):
                c2, ok = try_grow(cfg, i, s)
                if ok:
                    cfg = c2
                    improved = True
                    break
            # try nudging center
            for dx, dy in ((step*0.5,0),(-step*0.5,0),(0,step*0.5),(0,-step*0.5)):
                c2 = cfg.copy()
                c2[i, 0] += dx
                c2[i, 1] += dy
                c2 = repair(c2)
                if feasible(c2):
                    if c2[:, 2].sum() >= cfg[:, 2].sum() - 1e-15:
                        cfg = c2
                        improved = True
        if not improved:
            step *= 0.5
            if step < 1e-7:
                break
        if cfg[:, 2].sum() > best_score:
            best_score = cfg[:, 2].sum()
            best = cfg.copy()

    # final safety: shrink slightly
    out = best.copy()
    out[:, 2] *= (1.0 - 1e-9)
    out = repair(out)
    return out

import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    # Initialise from start (or fallback grid)
    if start is not None:
        s = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        s = np.array([[x, y, 0.02] for x, y in pts])

    # z = [x0..x31, y0..y31, r0..r31]
    z0 = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])

    def unpack(z):
        return z[0:n], z[n:2*n], z[2*n:3*n]

    def obj(z):
        return -np.sum(z[2*n:3*n])

    def obj_jac(z):
        g = np.zeros(3*n)
        g[2*n:3*n] = -1.0
        return g

    # Constraints list
    cons = []
    # wall constraints: x_i - r_i >= 0 ; 1 - x_i - r_i >= 0 ; y_i - r_i >=0 ; 1 - y_i - r_i >=0
    for i in range(n):
        def make_wall(i, kind):
            def f(z):
                x, y, r = unpack(z)
                if kind == 0:
                    return x[i] - r[i]
                elif kind == 1:
                    return 1.0 - x[i] - r[i]
                elif kind == 2:
                    return y[i] - r[i]
                else:
                    return 1.0 - y[i] - r[i]
            def j(z):
                g = np.zeros(3*n)
                if kind == 0:
                    g[i] = 1.0; g[2*n+i] = -1.0
                elif kind == 1:
                    g[i] = -1.0; g[2*n+i] = -1.0
                elif kind == 2:
                    g[n+i] = 1.0; g[2*n+i] = -1.0
                else:
                    g[n+i] = -1.0; g[2*n+i] = -1.0
                return g
            return f, j
        for kind in range(4):
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    # pair constraints
    for i in range(n):
        for j in range(i+1, n):
            def make_pair(i, j):
                def f(z):
                    x, y, r = unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx*dx + dy*dy - (r[i]+r[j])**2
                def jac(z):
                    x, y, r = unpack(z)
                    g = np.zeros(3*n)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2*dx; g[j] = -2*dx
                    g[n+i] = 2*dy; g[n+j] = -2*dy
                    sr = 2*(r[i]+r[j])
                    g[2*n+i] = -sr; g[2*n+j] = -sr
                    return g
                return f, jac
            f, jac = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})

    # Bounds: x,y in [0,1], r in (0, 0.5]
    bounds = [(0.0, 1.0)]*(2*n) + [(1e-6, 0.5)]*n

    # Run SLSQP with a time guard
    best = z0.copy()
    # Use a callback to stop when time is nearly up
    deadline = t0 + budget_seconds - 0.5
    class TimeUp(Exception):
        pass
    def cb(z):
        if time.process_time() > deadline:
            raise TimeUp()

    try:
        res = minimize(obj, z0, jac=obj_jac, method='SLSQP',
                       constraints=cons, bounds=bounds,
                       options={'maxiter': 2000, 'ftol': 1e-12},
                       callback=cb)
        best = res.x
    except TimeUp:
        pass
    except Exception:
        pass

    x, y, r = unpack(best)

    # Safety: shrink radii and clip centres
    r = np.maximum(r - 1e-9, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)

    out = np.column_stack([x, y, r])
    return out

