def _slsqp_polish(z0, n, deadline):
    """Run SLSQP on z0 with p0006's objective/constraints. Return best z or None."""
    def unpack(z):
        return z[0:n], z[n:2*n], z[2*n:3*n]

    def obj(z):
        return -np.sum(z[2*n:3*n])

    def obj_jac(z):
        g = np.zeros(3*n)
        g[2*n:3*n] = -1.0
        return g

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(z):
                    x, y, r = unpack(z)
                    if kind == 0:
                        return x[i] - r[i]
                    elif kind == 1:
                        return 1.0 - x[i] - r[i]
                    elif kind == 2:
                        return y[i] - r[i]
                    else:
                        return 1.0 - y[i] - r[i]
                def j(z):
                    g = np.zeros(3*n)
                    if kind == 0:
                        g[i] = 1.0; g[2*n+i] = -1.0
                    elif kind == 1:
                        g[i] = -1.0; g[2*n+i] = -1.0
                    elif kind == 2:
                        g[n+i] = 1.0; g[2*n+i] = -1.0
                    else:
                        g[n+i] = -1.0; g[2*n+i] = -1.0
                    return g
                return f, j
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i+1, n):
            def make_pair(i, j):
                def f(z):
                    x, y, r = unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx*dx + dy*dy - (r[i]+r[j])**2
                def jac(z):
                    x, y, r = unpack(z)
                    g = np.zeros(3*n)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2*dx; g[j] = -2*dx
                    g[n+i] = 2*dy; g[n+j] = -2*dy
                    sr = 2*(r[i]+r[j])
                    g[2*n+i] = -sr; g[2*n+j] = -sr
                    return g
                return f, jac
            f, jac = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})

    bounds = [(0.0, 1.0)]*(2*n) + [(1e-6, 0.5)]*n

    class TimeUp(Exception):
        pass
    def cb(z):
        if time.process_time() > deadline:
            raise TimeUp()

    try:
        res = minimize(obj, z0, jac=obj_jac, method='SLSQP',
                       constraints=cons, bounds=bounds,
                       options={'maxiter': 1000, 'ftol': 1e-12},
                       callback=cb)
        return res.x
    except TimeUp:
        return None
    except Exception:
        return None


def _random_insertion(n, rng):
    """Randomized largest-empty-circle insertion. Returns array (n,3)."""
    xs = np.zeros(n)
    ys = np.zeros(n)
    rs = np.zeros(n)
    for k in range(n):
        # sample candidates
        m = 200
        cx = rng.random(m)
        cy = rng.random(m)
        # distance to walls
        allowed = np.minimum(np.minimum(cx, 1.0 - cx), np.minimum(cy, 1.0 - cy))
        if k > 0:
            px = xs[:k]; py = ys[:k]; pr = rs[:k]
            dx = cx[:, None] - px[None, :]
            dy = cy[:, None] - py[None, :]
            d = np.sqrt(dx*dx + dy*dy) - pr[None, :]
            allowed = np.minimum(allowed, d.min(axis=1))
        allowed = np.maximum(allowed, 1e-6)
        # choose largest allowed but multiply by random factor
        score = allowed * rng.uniform(0.7, 1.0, m)
        idx = int(np.argmax(score))
        xs[k] = cx[idx]
        ys[k] = cy[idx]
        rs[k] = max(allowed[idx], 1e-6)
    return np.column_stack([xs, ys, rs])


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    deadline = t0 + budget_seconds - 0.6

    # Base result from start
    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        base = np.array([[x, y, 0.02] for x, y in pts])

    def to_z(s):
        return np.concatenate([s[:, 0], s[:, 1], s[:, 2]])

    def from_z(z):
        return np.column_stack([z[0:n], z[n:2*n], z[2*n:3*n]])

    def score(s):
        return float(np.sum(s[:, 2]))

    best = base.copy()
    best_score = score(best)

    # Polish the base first
    z = _slsqp_polish(to_z(base), n, deadline)
    if z is not None:
        s = from_z(z)
        sc = score(s)
        if sc > best_score:
            best = s
            best_score = sc

    rng = np.random.default_rng(12345)

    # Try randomized insertion seeds
    for trial in range(10):
        if time.process_time() > deadline:
            break
        seed = _random_insertion(n, rng)
        z = _slsqp_polish(to_z(seed), n, deadline)
        if z is not None:
            s = from_z(z)
            sc = score(s)
            if sc > best_score:
                best = s
                best_score = sc

    x = best[:, 0].copy()
    y = best[:, 1].copy()
    r = best[:, 2].copy()

    # Safety: shrink radii and clip centres
    r = np.maximum(r - 1e-9, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)

    return np.column_stack([x, y, r])

