def _valid(out):
    x = out[:, 0]; y = out[:, 1]; r = out[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -1e-12) or np.any(x + r > 1 + 1e-12):
        return False
    if np.any(y - r < -1e-12) or np.any(y + r > 1 + 1e-12):
        return False
    n = len(r)
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - 1e-12:
                return False
    return True


