            if 1.0 - y[i] - r[i] < 1e-7: walls.append((i, 3))
        return pairs, walls

    def near_pairs(z, thresh=0.02):
        x, y, r = unpack(z)
        out = []
        for i in range(n):
            for j in range(i+1, n):
                dx = x[i]-x[j]; dy = y[i]-y[j]
                d = np.hypot(dx, dy)
                gap = d - (r[i]+r[j])
                if 0 <= gap < thresh:
                    out.append((i, j))
        return out

    # ---- build equality constraints for a given contact set ----
    def wall_eq(i, kind):
        def f(z):
            x, y, r = unpack(z)
            if kind == 0: return x[i] - r[i]
            elif kind == 1: return 1.0 - x[i] - r[i]
            elif kind == 2: return y[i] - r[i]
            else: return 1.0 - y[i] - r[i]
        def j(z):
            g = np.zeros(3*n)
            if kind == 0:
                g[i] = 1.0; g[2*n+i] = -1.0
            elif kind == 1:
                g[i] = -1.0; g[2*n+i] = -1.0
            elif kind == 2:
                g[n+i] = 1.0; g[2*n+i] = -1.0
            else:
                g[n+i] = -1.0; g[2*n+i] = -1.0
            return g
        return {'type': 'eq', 'fun': f, 'jac': j}

    def pair_eq(i, j):
        def f(z):
            x, y, r = unpack(z)
            dx = x[i] - x[j]; dy = y[i] - y[j]
            return dx*dx + dy*dy - (r[i]+r[j])**2
        def jac(z):
            x, y, r = unpack(z)
            g = np.zeros(3*n)
            dx = x[i] - x[j]; dy = y[i] - y[j]
            g[i] = 2*dx; g[j] = -2*dx
            g[n+i] = 2*dy; g[n+j] = -2*dy
            sr = 2*(r[i]+r[j])
            g[2*n+i] = -sr; g[2*n+j] = -sr
            return g
        return {'type': 'eq', 'fun': f, 'jac': jac}

    def solve_eq(z_start, pairs, walls, maxiter=800, ftol=1e-10):
        cons = [pair_eq(i, j) for (i, j) in pairs] + [wall_eq(i, k) for (i, k) in walls]
        def cb(z):
            if time.process_time() > deadline:
                raise TimeUp()
        try:
            res = minimize(obj, z_start, jac=obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': ftol},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    # ---- main loop: modify contact graph ----
    rng = np.random.default_rng(98765)
    best_score = valid_score(best)
    cur_pairs, cur_walls = active_contacts(best)

    while time.process_time() < deadline:
        pairs = list(cur_pairs)
        walls = list(cur_walls)

        # random modification
        op = rng.integers(0, 3)
        if op == 0 and (pairs or walls):
            # remove one active contact
            if rng.random() < 0.5 and pairs:
                pairs.pop(rng.integers(0, len(pairs)))
            elif walls:
                walls.pop(rng.integers(0, len(walls)))
        elif op == 1:
            # add a near-contact pair
            np_ = near_pairs(best)
            if np_:
                p = np_[rng.integers(0, len(np_))]
                if p not in pairs:
                    pairs.append(p)
        else:
            # remove and add
            if pairs:
                pairs.pop(rng.integers(0, len(pairs)))
            np_ = near_pairs(best)
            if np_:
                p = np_[rng.integers(0, len(np_))]
                if p not in pairs:
                    pairs.append(p)

        z = solve_eq(best.copy(), pairs, walls)
        if z is None:
            continue
        sc = valid_score(z)
        if sc > best_score + 1e-12 and strict_valid(z):
            best = z
            best_score = sc
            cur_pairs, cur_walls = active_contacts(best)

    # ---- final repair: shrink radii to guarantee validity ----
    x, y, r = unpack(best)
    r = np.maximum(r - 1e-9, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)

    out = np.column_stack([x, y, r])
    return out

import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    if start is not None:
