        s = np.array([[x, y, 0.02] for x, y in pts])

    z0 = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])

    def unpack(z):
        return z[0:n], z[n:2*n], z[2*n:3*n]

    def obj(z):
        return -np.sum(z[2*n:3*n])

    def obj_jac(z):
        g = np.zeros(3*n)
        g[2*n:3*n] = -1.0
        return g

    # Pre-build wall constraints (always active).
    wall_cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(z):
                x, y, r = unpack(z)
                if kind == 0:
                    return x[i] - r[i]
                elif kind == 1:
                    return 1.0 - x[i] - r[i]
                elif kind == 2:
                    return y[i] - r[i]
                else:
                    return 1.0 - y[i] - r[i]
            def j(z):
                g = np.zeros(3*n)
                if kind == 0:
                    g[i] = 1.0; g[2*n+i] = -1.0
                elif kind == 1:
                    g[i] = -1.0; g[2*n+i] = -1.0
                elif kind == 2:
                    g[n+i] = 1.0; g[2*n+i] = -1.0
                else:
                    g[n+i] = -1.0; g[2*n+i] = -1.0
                return g
            return f, j
        for kind in range(4):
            f, j = make_wall(i, kind)
            wall_cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    # Pre-build all pair constraint factories.
    pair_factories = {}
    for i in range(n):
        for j in range(i+1, n):
            def make_pair(i, j):
                def f(z):
                    x, y, r = unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx*dx + dy*dy - (r[i]+r[j])**2
                def jac(z):
                    x, y, r = unpack(z)
                    g = np.zeros(3*n)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2*dx; g[j] = -2*dx
                    g[n+i] = 2*dy; g[n+j] = -2*dy
                    sr = 2*(r[i]+r[j])
                    g[2*n+i] = -sr; g[2*n+j] = -sr
                    return g
                return f, jac
            pair_factories[(i, j)] = make_pair(i, j)

    bounds = [(0.0, 1.0)]*(2*n) + [(1e-6, 0.5)]*n

    deadline = t0 + budget_seconds - 0.7

    class TimeUp(Exception):
        pass

    def active_pairs(z, thresh=0.03):
        x, y, r = unpack(z)
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        d = np.sqrt(dx*dx + dy*dy)
        rs = r[:, None] + r[None, :]
        gap = d - rs
        iu, ju = np.triu_indices(n, 1)
        mask = gap[iu, ju] < thresh
        return list(zip(iu[mask].tolist(), ju[mask].tolist()))

    def build_cons(pairs):
        cons = list(wall_cons)
        for (i, j) in pairs:
            f, jac = pair_factories[(i, j)]
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
        return cons

    def violated_pairs(z, tol=1e-9):
        x, y, r = unpack(z)
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        d = np.sqrt(dx*dx + dy*dy)
        rs = r[:, None] + r[None, :]
        gap = d - rs
        iu, ju = np.triu_indices(n, 1)
        mask = gap[iu, ju] < -tol
        return list(zip(iu[mask].tolist(), ju[mask].tolist()))

    def solve(z_start, maxiter, ftol):
        pairs = active_pairs(z_start)
        z = z_start
        for attempt in range(4):
            cons = build_cons(pairs)
