                               options={'maxiter': maxiter, 'ftol': ftol},
                               callback=cb)
                z = res.x
            except TimeUp:
                return None
            except Exception:
                return None
            bad = violated_pairs(z)
            if not bad:
                return z
            newpairs = set(pairs) | set(bad)
            if len(newpairs) == len(pairs):
                return z
            pairs = list(newpairs)
        return z

    def valid_score(z):
        x, y, r = unpack(z)
        if np.any(r <= 0):
            return -np.inf
        if np.any(x - r < -1e-9) or np.any(x + r > 1 + 1e-9):
            return -np.inf
        if np.any(y - r < -1e-9) or np.any(y + r > 1 + 1e-9):
            return -np.inf
        if violated_pairs(z):
            return -np.inf
        return np.sum(r)

    best = z0.copy()
    res0 = solve(z0, 2000, 1e-12)
    if res0 is not None and valid_score(res0) > valid_score(best):
        best = res0

    rng = np.random.default_rng(12345)
    it = 0
    while time.process_time() < deadline:
        it += 1
        z = best.copy()
        sx = rng.uniform(0.001, 0.02)
        sr = rng.uniform(0.0005, 0.005)
        z[0:n] += rng.normal(0, sx, n)
        z[n:2*n] += rng.normal(0, sx, n)
        z[2*n:3*n] += rng.normal(0, sr, n)
        z[0:n] = np.clip(z[0:n], 0.0, 1.0)
        z[n:2*n] = np.clip(z[n:2*n], 0.0, 1.0)
        z[2*n:3*n] = np.clip(z[2*n:3*n], 1e-6, 0.5)
        if it % 5 == 0:
            idx = rng.choice(n, size=2, replace=False)
            for k in idx:
                z[k] = rng.uniform(0.05, 0.95)
                z[n+k] = rng.uniform(0.05, 0.95)
                z[2*n+k] = 0.01
        res = solve(z, 400, 1e-10)
        if res is not None and valid_score(res) > valid_score(best):
            best = res

    x, y, r = unpack(best)
    r = np.maximum(r - 1e-9, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)

    out = np.column_stack([x, y, r])
    return out

