            z[0:N] = np.clip(z[0:N], 0.0, 1.0)
            z[N:2*N] = np.clip(z[N:2*N], 0.0, 1.0)
            z = _repair(z)
            res = solve(z, 600, 1e-10)
            if res is not None:
                evaluate(res)
        else:
            # Uniform growth of all radii (a "scale up" attempt)
            z[2*N:3*N] *= rng.uniform(1.005, 1.03)
            z[2*N:3*N] = np.clip(z[2*N:3*N], 1e-6, 0.5)
            z = _repair(z)
            res = solve(z, 800, 1e-10)
            if res is not None:
                evaluate(res)

    out = np.column_stack(_unpack(best_z))
    # Safety shrink
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    for _ in range(100):
        changed = False
        for i in range(N):
            x, y, r = out[i]
            lim = min(x, 1 - x, y, 1 - y) - 1e-12
            if r > lim:
                out[i, 2] = max(lim, 1e-9)
                changed = True
        for i in range(N):
            xi, yi, ri = out[i]
            for j in range(i + 1, N):
                xj, yj, rj = out[j]
                dx = xi - xj; dy = yi - yj
                d2 = dx * dx + dy * dy
                s = ri + rj + 1e-12
                if d2 < s * s:
                    d = np.sqrt(d2) if d2 > 0 else 1e-12
                    excess = s - d
                    total = ri + rj
                    if total > 0:
                        out[i, 2] = max(ri - excess * (ri / total), 1e-9)
                        out[j, 2] = max(rj - excess * (rj / total), 1e-9)
                    changed = True
        if not changed:
            break
    return out

import numpy as np
import time
from scipy.optimize import minimize

N = 32


def _unpack(z):
    return z[0:N], z[N:2*N], z[2*N:3*N]


def _obj(z):
    return -np.sum(z[2*N:3*N])


def _obj_jac(z):
    g = np.zeros(3*N)
    g[2*N:3*N] = -1.0
    return g


def _build_cons():
    cons = []
    for i in range(N):
        for kind in range(4):
            def make(i, kind):
                def f(z):
                    x, y, r = _unpack(z)
                    if kind == 0:
                        return x[i] - r[i]
                    if kind == 1:
                        return 1.0 - x[i] - r[i]
                    if kind == 2:
                        return y[i] - r[i]
                    return 1.0 - y[i] - r[i]

                def j(z):
                    g = np.zeros(3*N)
                    if kind == 0:
                        g[i] = 1.0; g[2*N+i] = -1.0
                    elif kind == 1:
                        g[i] = -1.0; g[2*N+i] = -1.0
                    elif kind == 2:
                        g[N+i] = 1.0; g[2*N+i] = -1.0
                    else:
                        g[N+i] = -1.0; g[2*N+i] = -1.0
                    return g
                return f, j
            f, j = make(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(N):
        for j in range(i+1, N):
            def make(i, j):
                def f(z):
                    x, y, r = _unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx*dx + dy*dy - (r[i] + r[j])**2

                def jac(z):
                    x, y, r = _unpack(z)
                    g = np.zeros(3*N)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2*dx; g[j] = -2*dx
                    g[N+i] = 2*dy; g[N+j] = -2*dy
                    sr = 2*(r[i] + r[j])
                    g[2*N+i] = -sr; g[2*N+j] = -sr
                    return g
                return f, jac
            f, jac = make(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _repair(z):
    """Make z strictly feasible, shrinking radii where needed."""
    x, y, r = _unpack(z.copy())
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(200):
        changed = False
        for i in range(N):
            for j in range(i+1, N):
                d = np.hypot(x[i]-x[j], y[i]-y[j])
                s = r[i] + r[j]
                if d < s:
                    ex = (s - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - ex, 1e-6)
                    r[j] = max(r[j] - ex, 1e-6)
                    changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    r = np.maximum(r - 1e-8, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.concatenate([x, y, r])


def _greedy_seed():
    """Greedy largest-empty-circle construction."""
    xs = np.linspace(0.0025, 0.9975, 200)
    ys = np.linspace(0.0025, 0.9975, 200)
    GX, GY = np.meshgrid(xs, ys)
    cx = np.array([0.5]); cy = np.array([0.5]); cr = np.array([0.1])
    for k in range(1, N):
        dx = GX[..., None] - cx[None, None, :]
        dy = GY[..., None] - cy[None, None, :]
        dcirc = np.sqrt(dx*dx + dy*dy).min(axis=2)
        dwall = np.minimum(np.minimum(GX, 1.0-GX), np.minimum(GY, 1.0-GY))
        d = np.minimum(dcirc, dwall)
        idx = np.unravel_index(np.argmax(d), d.shape)
        cx = np.append(cx, GX[idx]); cy = np.append(cy, GY[idx])
        cr = np.append(cr, 0.9 * d[idx])
    return np.concatenate([cx, cy, cr])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    cons = _build_cons()
    bounds = [(0.0, 1.0)] * (2*N) + [(1e-6, 0.5)] * N

    class TimeUp(Exception):
        pass

    best_z = None
    best_val = -np.inf

    def evaluate(z):
        nonlocal best_z, best_val
        zf = _repair(z)
        val = np.sum(zf[2*N:3*N])
        if val > best_val:
            best_val = val
            best_z = zf.copy()

    def solve(z_start, maxiter, ftol):
        if time.process_time() > deadline:
            return None

        def cb(z):
            if time.process_time() > deadline:
                raise TimeUp()

        try:
            res = minimize(_obj, z_start, jac=_obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': ftol},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    # Fresh greedy seed (ignore start)
    z_seed = _repair(_greedy_seed())
    evaluate(z_seed)

    res0 = solve(z_seed, 3000, 1e-12)
    if res0 is not None:
        evaluate(res0)

    rng = np.random.default_rng(12345)
    for _ in range(3):
        if time.process_time() > deadline:
            break
        z = z_seed.copy()
        z[0:N] += rng.normal(0, 0.01, N)
        z[N:2*N] += rng.normal(0, 0.01, N)
        z[0:N] = np.clip(z[0:N], 0.0, 1.0)
        z[N:2*N] = np.clip(z[N:2*N], 0.0, 1.0)
        z = _repair(z)
        res = solve(z, 1000, 1e-10)
        if res is not None:
            evaluate(res)

    # Use remaining time for extra perturbations from best
    while time.process_time() < deadline:
        z = best_z.copy()
        sx = 0.01
        z[0:N] += rng.normal(0, sx, N)
        z[N:2*N] += rng.normal(0, sx, N)
        z[0:N] = np.clip(z[0:N], 0.0, 1.0)
        z[N:2*N] = np.clip(z[N:2*N], 0.0, 1.0)
        z = _repair(z)
        res = solve(z, 500, 1e-10)
        if res is not None:
            evaluate(res)

    return np.column_stack(_unpack(best_z))

