def _lp_radii(x, y):
    """Given centers, maximize sum r subject to r_i+r_j <= dist_ij, r_i <= wall dists."""
    n = N
    c = -np.ones(n)
    # pair constraints: r_i + r_j <= d_ij
    rows = []
    rhs = []
    for i in range(n):
        for j in range(i+1, n):
            row = np.zeros(n)
            row[i] = 1.0; row[j] = 1.0
            rows.append(row)
            rhs.append(np.hypot(x[i]-x[j], y[i]-y[j]))
    # wall constraints
    for i in range(n):
        row = np.zeros(n); row[i] = 1.0
        rows.append(row); rhs.append(min(x[i], 1-x[i], y[i], 1-y[i]))
    A_ub = np.array(rows)
    b_ub = np.array(rhs)
    bounds = [(0, None)] * n
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method='highs')
        if res.success:
            return res.x
    except Exception:
        pass
    return None


def _resolve_overlaps(x, y, r, steps=50):
    """Projected gradient: push overlapping pairs apart, clip to walls."""
    x = x.copy(); y = y.copy()
    n = N
    for _ in range(steps):
        max_ov = 0.0
        dx = np.zeros(n); dy = np.zeros(n)
        for i in range(n):
            for j in range(i+1, n):
                ddx = x[i]-x[j]; ddy = y[i]-y[j]
                d = np.hypot(ddx, ddy)
                s = r[i]+r[j]
                if d < s:
                    ov = s - d
                    max_ov = max(max_ov, ov)
                    if d < 1e-12:
                        ddx, ddy, d = 1.0, 0.0, 1.0
                    ux = ddx/d; uy = ddy/d
                    dx[i] += 0.5*ov*ux; dy[i] += 0.5*ov*uy
                    dx[j] -= 0.5*ov*ux; dy[j] -= 0.5*ov*uy
        x += dx; y += dy
        x = np.clip(x, r, 1.0-r)
        y = np.clip(y, r, 1.0-r)
        if max_ov < 1e-10:
            return x, y, True
    return x, y, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    cons = _build_cons()
    bounds = [(0.0, 1.0)] * (2*N) + [(1e-6, 0.5)] * N

