            return None

        def cb(z):
            if time.process_time() > deadline:
                raise TimeUp()

        try:
            res = minimize(_obj, z_start, jac=_obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': ftol},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    # Seed from start
    if start is not None:
        s = np.asarray(start, dtype=float)
        z_init = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5*(j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_init = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_init = _repair(z_init)
    evaluate(z_init)

    res0 = solve(z_init, 3000, 1e-12)
    if res0 is not None:
        evaluate(res0)

    # ---- Lubachevsky-Stillinger style inflation ----
    rng = np.random.default_rng(2024)
    if best_z is not None:
        x, y, r = _unpack(best_z.copy())
        r = r * 0.95
        x = np.clip(x, r, 1.0-r)
        y = np.clip(y, r, 1.0-r)

        while time.process_time() < deadline:
            r = r * 1.002
            x, y, ok = _resolve_overlaps(x, y, r, steps=50)
            if ok:
