import numpy as np
import time
from scipy.optimize import minimize, linprog

N = 32


def _unpack(z):
    return z[0:N], z[N:2*N], z[2*N:3*N]


def _obj(z):
    return -np.sum(z[2*N:3*N])


def _obj_jac(z):
    g = np.zeros(3*N)
    g[2*N:3*N] = -1.0
    return g


def _build_cons():
    cons = []
    for i in range(N):
        for kind in range(4):
            def make(i, kind):
                def f(z):
                    x, y, r = _unpack(z)
                    if kind == 0:
                        return x[i] - r[i]
                    if kind == 1:
                        return 1.0 - x[i] - r[i]
                    if kind == 2:
                        return y[i] - r[i]
                    return 1.0 - y[i] - r[i]

                def j(z):
                    g = np.zeros(3*N)
                    if kind == 0:
                        g[i] = 1.0; g[2*N+i] = -1.0
                    elif kind == 1:
                        g[i] = -1.0; g[2*N+i] = -1.0
                    elif kind == 2:
                        g[N+i] = 1.0; g[2*N+i] = -1.0
                    else:
                        g[N+i] = -1.0; g[2*N+i] = -1.0
                    return g
                return f, j
            f, j = make(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(N):
        for j in range(i+1, N):
            def make(i, j):
                def f(z):
                    x, y, r = _unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx*dx + dy*dy - (r[i] + r[j])**2

                def jac(z):
                    x, y, r = _unpack(z)
                    g = np.zeros(3*N)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2*dx; g[j] = -2*dx
                    g[N+i] = 2*dy; g[N+j] = -2*dy
                    sr = 2*(r[i] + r[j])
                    g[2*N+i] = -sr; g[2*N+j] = -sr
                    return g
                return f, jac
            f, jac = make(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _repair(z):
    """Make z strictly feasible, shrinking radii where needed."""
    x, y, r = _unpack(z.copy())
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(200):
        changed = False
        for i in range(N):
            for j in range(i+1, N):
                d = np.hypot(x[i]-x[j], y[i]-y[j])
                s = r[i] + r[j]
                if d < s:
                    ex = (s - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - ex, 1e-6)
                    r[j] = max(r[j] - ex, 1e-6)
                    changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    r = np.maximum(r - 1e-8, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.concatenate([x, y, r])


def _lp_radii(x, y):
    """For fixed centers, maximize sum(r) s.t. r_i+r_j <= dist_ij, r_i <= wall."""
    n = N
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i+1, n):
            d = np.hypot(x[i]-x[j], y[i]-y[j])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    for i in range(n):
        row = np.zeros(n)
        row[i] = 1.0
        A_ub.append(row)
        b_ub.append(min(x[i], 1.0-x[i], y[i], 1.0-y[i]))
    A_ub = np.array(A_ub)
    b_ub = np.array(b_ub)
    bounds = [(0.0, None)] * n
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-9)
    except Exception:
        pass
    return None


def _row_seeds():
    """Enumerate row-count partitions summing to 32 with k=5,6,7, n_i in {4,5,6,7}."""
    seeds = []
    allowed = (4, 5, 6, 7)
    for k in (5, 6, 7):
        def rec(prefix, remaining, slots):
            if slots == 0:
                if remaining == 0:
                    seeds.append(tuple(prefix))
                return
            for v in allowed:
                if v <= remaining and remaining - v <= 7 * (slots - 1):
                    rec(prefix + [v], remaining - v, slots - 1)
        rec([], N, k)
    return seeds


def _pattern_to_z(pattern):
    k = len(pattern)
    xs = []
    ys = []
    idx = 0
    for i, n_i in enumerate(pattern):
        y = (i + 0.5) / k
        offset = 0.5 / n_i if (i % 2 == 1) else 0.0
        for j in range(n_i):
            x = (j + 0.5) / n_i + offset
            xs.append(x)
            ys.append(y)
            idx += 1
    xs = np.array(xs[:N])
    ys = np.array(ys[:N])
    # scale into [0.05, 0.95]
    xs = 0.05 + 0.9 * xs
    ys = 0.05 + 0.9 * ys
    rs = np.full(N, 0.04)
    return np.concatenate([xs, ys, rs])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    cons = _build_cons()
    bounds = [(0.0, 1.0)] * (2*N) + [(1e-6, 0.5)] * N

    class TimeUp(Exception):
        pass

    best_z = None
    best_val = -np.inf

    def evaluate(z):
        nonlocal best_z, best_val
        zf = _repair(z)
        val = np.sum(zf[2*N:3*N])
        if val > best_val:
            best_val = val
            best_z = zf.copy()

    def solve(z_start, maxiter, ftol):
        if time.process_time() > deadline:
            return None

        def cb(z):
            if time.process_time() > deadline:
                raise TimeUp()

        try:
            res = minimize(_obj, z_start, jac=_obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': ftol},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    def polish(z):
        """LP-polish radii for fixed centers, then short SLSQP."""
        x, y, r = _unpack(z.copy())
        rlp = _lp_radii(x, y)
        if rlp is not None:
            z2 = np.concatenate([x, y, rlp])
            z2 = _repair(z2)
            evaluate(z2)
            res = solve(z2, 200, 1e-11)
            if res is not None:
                evaluate(res)
                return res
            return z2
        return z

    if start is not None:
        s = np.asarray(start, dtype=float)
        z_init = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5*(j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_init = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_init = _repair(z_init)
    evaluate(z_init)

    res0 = solve(z_init, 3000, 1e-12)
    if res0 is not None:
        evaluate(res0)
        polish(res0)

    # Deterministic row-pattern seeds
    patterns = _row_seeds()
    for pat in patterns:
        if time.process_time() > deadline:
            break
        zp = _pattern_to_z(pat)
        zp = _repair(zp)
        res = solve(zp, 2000, 1e-11)
        if res is not None:
            evaluate(res)
            if time.process_time() < deadline:
                polish(res)

    rng = np.random.default_rng(2024)
    it = 0
    while time.process_time() < deadline:
        it += 1
        z = best_z.copy()
        frac = (time.process_time() - t0) / max(deadline - t0, 1e-9)
        scale = 1.0 - 0.6 * min(frac, 1.0)
        sx = rng.uniform(0.002, 0.02) * scale
        sr = rng.uniform(0.001, 0.006) * scale
        z[0:N] += rng.normal(0, sx, N)
        z[N:2*N] += rng.normal(0, sx, N)
        z[2*N:3*N] += rng.normal(0, sr, N)
        z[0:N] = np.clip(z[0:N], 0.0, 1.0)
        z[N:2*N] = np.clip(z[N:2*N], 0.0, 1.0)
        z[2*N:3*N] = np.clip(z[2*N:3*N], 1e-6, 0.5)
        if rng.random() < 0.15:
            for k in rng.choice(N, size=rng.integers(1, 3), replace=False):
                z[k] = rng.uniform(0.1, 0.9)
                z[N+k] = rng.uniform(0.1, 0.9)
                z[2*N+k] = rng.uniform(0.02, 0.08)
        res = solve(z, 600, 1e-10)
        if res is not None:
            evaluate(res)
            if time.process_time() < deadline:
                polish(res)

    return np.column_stack(_unpack(best_z))

