def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    cons = _build_cons()
    bounds = [(0.0, 1.0)] * (2*N) + [(1e-6, 0.5)] * N

    class TimeUp(Exception):
        pass

    best_z = None
    best_val = -np.inf

    def evaluate(z):
        nonlocal best_z, best_val
        zf = _repair(z)
        val = np.sum(zf[2*N:3*N])
        if val > best_val:
            best_val = val
            best_z = zf.copy()

    def solve(z_start, maxiter, ftol):
        if time.process_time() > deadline:
            return None

        def cb(z):
            if time.process_time() > deadline:
                raise TimeUp()

        try:
            res = minimize(_obj, z_start, jac=_obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': ftol},
                           callback=cb)
