        rlp = _lp_radii(x, y)
        if rlp is not None:
            z2 = np.concatenate([x, y, rlp])
            z2 = _repair(z2)
            evaluate(z2)
            res = solve(z2, 200, 1e-11)
            if res is not None:
                evaluate(res)
                return res
            return z2
        return z

    if start is not None:
        s = np.asarray(start, dtype=float)
        z_init = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5*(j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_init = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_init = _repair(z_init)
    evaluate(z_init)

    res0 = solve(z_init, 3000, 1e-12)
    if res0 is not None:
        evaluate(res0)
        polish(res0)

    # Simulated annealing on centers only.
    rng = np.random.default_rng(12345)

    # Current centers
    cur_x = best_z[0:N].copy()
    cur_y = best_z[N:2*N].copy()
    cur_r = _lp_radii(cur_x, cur_y)
    if cur_r is None:
        cur_r = best_z[2*N:3*N].copy()
    cur_val = float(np.sum(cur_r))

    # Annealing schedule based on remaining time
    anneal_end = t0 + (deadline - t0) * 0.75

    def slsqp_centers(x, y, maxiter):
        """SLSQP on 64 center coords with objective -sum(LP radii)."""
        if time.process_time() > deadline:
            return None
        z0 = np.concatenate([x, y, _lp_radii(x, y) if _lp_radii(x, y) is not None else np.full(N, 0.05)])
        z0 = _repair(z0)

        def obj_c(zc):
            xx = zc[0:N]; yy = zc[N:2*N]
            s = _lp_sum(xx, yy)
            return -s if np.isfinite(s) else 1e6

