            res = minimize(obj_c, np.concatenate([x, y]), method='Nelder-Mead',
                           options={'maxiter': maxiter, 'xatol': 1e-6, 'fatol': 1e-8},
                           callback=cb)
            return res.x[0:N], res.x[N:2*N]
        except TimeUp:
            return None
        except Exception:
