        frac = min(max(frac, 0.0), 1.0)
        sigma = 0.02 * (1.0 - frac) + 0.002 * frac
        T = 1e-3 * (1.0 - frac) + 1e-5 * frac

        nx = cur_x + rng.normal(0, sigma, N)
        ny = cur_y + rng.normal(0, sigma, N)
        if rng.random() < 0.2:
            k = rng.integers(1, 5)
            idx = rng.choice(N, size=k, replace=False)
            nx[idx] = rng.uniform(0.1, 0.9, k)
            ny[idx] = rng.uniform(0.1, 0.9, k)
        nx = np.clip(nx, 0.0, 1.0)
        ny = np.clip(ny, 0.0, 1.0)

