            z = res.x
        except Exception:
            break
        P *= 10.0
    return _repair(z)


def _slsqp_polish(z_init, cons, bounds, deadline):
    class TimeUp(Exception):
        pass

    def cb(zz):
        if time.process_time() > deadline:
            raise TimeUp()
    try:
        res = minimize(_obj, z_init.copy(), jac=_obj_jac, method='SLSQP',
                       constraints=cons, bounds=bounds,
                       options={'maxiter': 500, 'ftol': 1e-13},
                       callback=cb)
        return _repair(res.x)
    except Exception:
        return _repair(z_init)


def _seed_staggered(nx, ny, jitter, rng):
    pts = []
    for j in range(ny):
        for i in range(nx):
            ox = 0.5 * (j % 2)
            pts.append(((i + 0.5 + ox) / nx, (j + 0.5) / ny))
    pts = pts[:N]
    while len(pts) < N:
        pts.append((rng.rand(), rng.rand()))
    x = np.array([p[0] for p in pts])
    y = np.array([p[1] for p in pts])
    x = np.clip(x + jitter * (rng.rand(N) - 0.5), 0.02, 0.98)
    y = np.clip(y + jitter * (rng.rand(N) - 0.5), 0.02, 0.98)
    r = np.full(N, 0.04)
    return np.concatenate([x, y, r])


def _seed_grid_removed(nx, ny, remove_idx, jitter, rng):
    pts = []
    for j in range(ny):
        for i in range(nx):
            idx = j * nx + i
            if idx in remove_idx:
                continue
            pts.append(((i + 0.5) / nx, (j + 0.5) / ny))
    pts = pts[:N]
    while len(pts) < N:
        pts.append((rng.rand(), rng.rand()))
    x = np.array([p[0] for p in pts])
    y = np.array([p[1] for p in pts])
    x = np.clip(x + jitter * (rng.rand(N) - 0.5), 0.02, 0.98)
    y = np.clip(y + jitter * (rng.rand(N) - 0.5), 0.02, 0.98)
    r = np.full(N, 0.04)
    return np.concatenate([x, y, r])


def _seed_ring_core(jitter, rng):
    pts = []
    # ring of 20
    nring = 20
    for k in range(nring):
        a = 2 * np.pi * k / nring
        pts.append((0.5 + 0.42 * np.cos(a), 0.5 + 0.42 * np.sin(a)))
    # core of 12
    ncore = N - nring
    for k in range(ncore):
        a = 2 * np.pi * k / ncore
        pts.append((0.5 + 0.18 * np.cos(a), 0.5 + 0.18 * np.sin(a)))
    x = np.array([p[0] for p in pts])
    y = np.array([p[1] for p in pts])
    x = np.clip(x + jitter * (rng.rand(N) - 0.5), 0.02, 0.98)
    y = np.clip(y + jitter * (rng.rand(N) - 0.5), 0.02, 0.98)
    r = np.full(N, 0.04)
    return np.concatenate([x, y, r])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    bounds = [(0.0, 1.0)] * (2*N) + [(1e-6, 0.5)] * N
    cons = _build_cons()

    if start is not None:
        s = np.asarray(start, dtype=float)
        z_best = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5*(j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_best = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_best = _repair(z_best)
    best_val = float(np.sum(z_best[2*N:3*N]))

    # Build deterministic seeds
    rng = np.random.RandomState(2024)
    seeds = []
    seeds.append(_seed_staggered(5, 7, 0.01, rng))   # 5x7 staggered
    seeds.append(_seed_staggered(4, 8, 0.01, rng))   # 4x8 staggered
    seeds.append(_seed_grid_removed(6, 6, {0, 5, 30, 35}, 0.01, rng))  # 6x6 minus 4
    seeds.append(_seed_ring_core(0.01, rng))         # ring + core

    # Time slices for restarts
    n_restarts = len(seeds)
    now = time.process_time()
    remaining = max(0.0, deadline - now)
    slice_time = remaining / (n_restarts + 1)

    for si, zseed in enumerate(seeds):
        if time.process_time() >= deadline:
            break
        slice_deadline = min(deadline, time.process_time() + slice_time)
        zs = _repair(zseed)
        zs = _penalty_opt(zs, slice_deadline, bounds)
        if time.process_time() < slice_deadline:
            zs = _slsqp_polish(zs, cons, bounds, slice_deadline)
        val = float(np.sum(zs[2*N:3*N]))
        if val > best_val + 1e-12:
            best_val = val
            z_best = zs.copy()

    # Final SLSQP polish on best if time remains
    if time.process_time() < deadline:
        zp = _slsqp_polish(z_best, cons, bounds, deadline)
        val = float(np.sum(zp[2*N:3*N]))
        if val > best_val + 1e-12:
            best_val = val
            z_best = zp.copy()

    x, y, r = _unpack(z_best)
    r = r - 1e-12
    r = np.maximum(r, 1e-12)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])

import numpy as np
import time
from scipy.optimize import minimize

N = 32


def _unpack(z):
    return z[0:N], z[N:2*N], z[2*N:3*N]


def _repair(z, rmin=1e-9):
    x, y, r = _unpack(z.copy())
    r = np.maximum(r, rmin)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(300):
        changed = False
        for i in range(N):
            for j in range(i + 1, N):
                d = np.hypot(x[i] - x[j], y[i] - y[j])
                s = r[i] + r[j]
                if d < s:
                    ex = (s - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - ex, rmin)
                    r[j] = max(r[j] - ex, rmin)
                    changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    return np.concatenate([x, y, r])


def _build_cons():
    cons = []
    for i in range(N):
        for kind in range(4):
            def make(i, kind):
                def f(z):
                    x, y, r = _unpack(z)
                    if kind == 0:
                        return x[i] - r[i]
                    if kind == 1:
                        return 1.0 - x[i] - r[i]
                    if kind == 2:
                        return y[i] - r[i]
                    return 1.0 - y[i] - r[i]

                def j(z):
                    g = np.zeros(3 * N)
                    if kind == 0:
                        g[i] = 1.0; g[2 * N + i] = -1.0
                    elif kind == 1:
                        g[i] = -1.0; g[2 * N + i] = -1.0
                    elif kind == 2:
                        g[N + i] = 1.0; g[2 * N + i] = -1.0
                    else:
                        g[N + i] = -1.0; g[2 * N + i] = -1.0
                    return g
                return f, j
            f, j = make(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(N):
        for j in range(i + 1, N):
            def make(i, j):
                def f(z):
                    x, y, r = _unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx * dx + dy * dy - (r[i] + r[j]) ** 2

                def jac(z):
                    x, y, r = _unpack(z)
                    g = np.zeros(3 * N)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2 * dx; g[j] = -2 * dx
                    g[N + i] = 2 * dy; g[N + j] = -2 * dy
                    sr = 2 * (r[i] + r[j])
                    g[2 * N + i] = -sr; g[2 * N + j] = -sr
                    return g
                return f, jac
            f, jac = make(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _obj(z):
    return -np.sum(z[2 * N:3 * N])


def _obj_jac(z):
    g = np.zeros(3 * N)
    g[2 * N:3 * N] = -1.0
    return g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    if start is not None:
        s = np.asarray(start, dtype=float)
        z_best = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5 * (j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_best = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_best = _repair(z_best)
    best_val = float(np.sum(z_best[2 * N:3 * N]))

    bounds = [(0.0, 1.0)] * (2 * N) + [(1e-9, 0.5)] * N
    cons = _build_cons()

    class TimeUp(Exception):
        pass

    def slsqp_polish(z_start, maxiter):
        def cb(zz):
            if time.process_time() > deadline:
                raise TimeUp()
        try:
            res = minimize(_obj, z_start.copy(), jac=_obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': 1e-14},
                           callback=cb)
            zr = _repair(res.x)
            return zr, float(np.sum(zr[2 * N:3 * N]))
        except Exception:
            return z_start.copy(), float(np.sum(z_start[2 * N:3 * N]))

    # Phase 1: SLSQP polish from start
    zr, val = slsqp_polish(z_best, 2000)
    if val > best_val:
        best_val = val
        z_best = zr

    # Phase 2: coordinate-wise "push into contact" moves + SLSQP polish.
    # This is the key diversification: find circles with slack and push
    # them toward their nearest neighbour, then re-optimize.
    rng = np.random.RandomState(20240617)
    tries = 0
    while time.process_time() < deadline - 0.3:
        tries += 1
        x, y, r = _unpack(z_best.copy())
        # compute per-circle slack (min gap to any other circle or wall)
        slack = np.full(N, 1e9)
        nearest = np.full(N, -1, dtype=int)
        for i in range(N):
            for j in range(N):
                if i == j:
                    continue
                d = np.hypot(x[i] - x[j], y[i] - y[j]) - (r[i] + r[j])
                if d < slack[i]:
                    slack[i] = d
                    nearest[i] = j
            w = min(x[i] - r[i], 1 - x[i] - r[i],
                    y[i] - r[i], 1 - y[i] - r[i])
            if w < slack[i]:
                slack[i] = w
                nearest[i] = -1
        # pick the circle(s) with most slack and push them
        order = np.argsort(-slack)
        n_push = rng.randint(1, 4)
        z = z_best.copy()
        for k in range(n_push):
            i = order[k % N]
            if nearest[i] >= 0:
                j = nearest[i]
                dx = x[j] - x[i]; dy = y[j] - y[i]
                d = np.hypot(dx, dy)
                if d > 1e-9:
                    step = min(slack[i] * 0.9 + 1e-3, 0.05) / d
                    z[i] += dx * step
                    z[N + i] += dy * step
            else:
                # push toward center
                cx = 0.5 - x[i]; cy = 0.5 - y[i]
                d = np.hypot(cx, cy)
                if d > 1e-9:
                    step = min(slack[i] * 0.9 + 1e-3, 0.05) / d
                    z[i] += cx * step
                    z[N + i] += cy * step
        # small jitter
        scale = 0.005 + 0.01 * rng.rand()
        z[:2 * N] += rng.randn(2 * N) * scale
        z = _repair(z)
        zr, val = slsqp_polish(z, 400)
        if val > best_val + 1e-11:
            best_val = val
            z_best = zr
            print(f"improved {best_val:.9f} try {tries}")

    # Final safety shrink
    x, y, r = _unpack(z_best)
    r = np.maximum(r - 1e-11, 1e-11)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    # verify & shrink more if needed
    for _ in range(5):
        bad = False
        for i in range(N):
            if (x[i] - r[i] < 0 or x[i] + r[i] > 1 or
                    y[i] - r[i] < 0 or y[i] + r[i] > 1):
                bad = True
        for i in range(N):
            for j in range(i + 1, N):
                d = np.hypot(x[i] - x[j], y[i] - y[j])
                if d < r[i] + r[j]:
                    bad = True
        if not bad:
            break
        r = np.maximum(r - 1e-10, 1e-11)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])

