                    r[j] = max(r[j] - ex, 1e-6)
                    changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    return np.concatenate([x, y, r])


def _penalty_obj_grad(z, P):
    x = z[0:N]; y = z[N:2*N]; r = z[2*N:3*N]
    g = np.zeros(3*N)
    g[2*N:3*N] = -1.0
    f = -np.sum(r)
    v = x - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[0:N][mask] += 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    v = 1.0 - x - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[0:N][mask] -= 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    v = y - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[N:2*N][mask] += 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    v = 1.0 - y - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[N:2*N][mask] -= 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    for i in range(N):
        for j in range(i+1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = np.hypot(dx, dy)
            s = r[i] + r[j]
            v = s - d
            if v > 0:
                f += P * v * v
                if d > 1e-12:
                    coef = 2*P*v / d
                    g[i] += -coef * dx
                    g[j] += coef * dx
                    g[N+i] += -coef * dy
                    g[N+j] += coef * dy
                g[2*N+i] += 2*P*v
                g[2*N+j] += 2*P*v
    return f, g


