                    sr = 2*(r[i] + r[j])
                    g[2*N+i] = -sr; g[2*N+j] = -sr
                    return g
                return f, jac
            f, jac = make(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _obj(z):
