                        rj = z[2*N+j] - sign * delta
                        if ri <= 1e-6 or rj <= 1e-6:
                            continue
                        z[2*N+i] = ri
                        z[2*N+j] = rj
                        z = _repair(z)
                        try:
                            res = minimize(_obj, z, jac=_obj_jac, method='SLSQP',
                                           constraints=cons, bounds=bounds,
                                           options={'maxiter': 200, 'ftol': 1e-13},
                                           callback=cb3)
                            zr = _repair(res.x)
                            val = float(np.sum(zr[2*N:3*N]))
                            if val > best_val + 1e-12:
                                best_val = val
                                z_best = zr.copy()
                        except Exception:
                            pass

    x, y, r = _unpack(z_best)
    r = r - 1e-12
    r = np.maximum(r, 1e-12)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])

import numpy as np
import time
from scipy.optimize import minimize

N = 32


def _unpack(z):
    return z[0:N], z[N:2*N], z[2*N:3*N]


def _repair(z):
    x, y, r = _unpack(z.copy())
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(300):
        changed = False
        for i in range(N):
            for j in range(i+1, N):
                d = np.hypot(x[i]-x[j], y[i]-y[j])
                s = r[i] + r[j]
                if d < s:
                    ex = (s - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - ex, 1e-6)
                    r[j] = max(r[j] - ex, 1e-6)
                    changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    return np.concatenate([x, y, r])


def _penalty_obj_grad(z, P):
    x = z[0:N]; y = z[N:2*N]; r = z[2*N:3*N]
    g = np.zeros(3*N)
    g[2*N:3*N] = -1.0
    f = -np.sum(r)
    v = x - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[0:N][mask] += 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    v = 1.0 - x - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[0:N][mask] -= 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    v = y - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[N:2*N][mask] += 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    v = 1.0 - y - r
    mask = v < 0
    if np.any(mask):
        f += P * np.sum(v[mask]**2)
        g[N:2*N][mask] -= 2*P*v[mask]
        g[2*N:3*N][mask] -= 2*P*v[mask]
    for i in range(N):
        for j in range(i+1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = np.hypot(dx, dy)
            s = r[i] + r[j]
            v = s - d
            if v > 0:
                f += P * v * v
                if d > 1e-12:
                    coef = 2*P*v / d
                    g[i] += -coef * dx
                    g[j] += coef * dx
                    g[N+i] += -coef * dy
                    g[N+j] += coef * dy
                g[2*N+i] += 2*P*v
                g[2*N+j] += 2*P*v
    return f, g


def _build_cons():
    cons = []
    for i in range(N):
        for kind in range(4):
            def make(i, kind):
                def f(z):
                    x, y, r = _unpack(z)
                    if kind == 0:
                        return x[i] - r[i]
                    if kind == 1:
                        return 1.0 - x[i] - r[i]
                    if kind == 2:
                        return y[i] - r[i]
                    return 1.0 - y[i] - r[i]

                def j(z):
                    g = np.zeros(3*N)
                    if kind == 0:
                        g[i] = 1.0; g[2*N+i] = -1.0
                    elif kind == 1:
                        g[i] = -1.0; g[2*N+i] = -1.0
                    elif kind == 2:
                        g[N+i] = 1.0; g[2*N+i] = -1.0
                    else:
                        g[N+i] = -1.0; g[2*N+i] = -1.0
                    return g
                return f, j
            f, j = make(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(N):
        for j in range(i+1, N):
            def make(i, j):
                def f(z):
                    x, y, r = _unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx*dx + dy*dy - (r[i] + r[j])**2

                def jac(z):
                    x, y, r = _unpack(z)
                    g = np.zeros(3*N)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2*dx; g[j] = -2*dx
                    g[N+i] = 2*dy; g[N+j] = -2*dy
                    sr = 2*(r[i] + r[j])
                    g[2*N+i] = -sr; g[2*N+j] = -sr
                    return g
                return f, jac
            f, jac = make(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _obj(z):
    return -np.sum(z[2*N:3*N])


def _obj_jac(z):
    g = np.zeros(3*N)
    g[2*N:3*N] = -1.0
    return g


def _largest_empty(x, y, r, skip, G=48):
    gs = np.linspace(0.0, 1.0, G)
    X, Y = np.meshgrid(gs, gs)
    wd = np.minimum(np.minimum(X, 1.0 - X), np.minimum(Y, 1.0 - Y))
    mind = wd.copy()
    for j in range(N):
        if j == skip:
            continue
        d = np.hypot(X - x[j], Y - y[j]) - r[j]
        mind = np.minimum(mind, d)
    idx = np.argmax(mind)
    return X.flat[idx], Y.flat[idx], mind.flat[idx]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7

    if start is not None:
        s = np.asarray(start, dtype=float)
        z_best = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5*(j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_best = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_best = _repair(z_best)
    best_val = float(np.sum(z_best[2*N:3*N]))

    bounds = [(0.0, 1.0)] * (2*N) + [(1e-6, 0.5)] * N
    cons = _build_cons()

    class TimeUp(Exception):
        pass

    def make_cb():
        def cb(zz):
            if time.process_time() > deadline:
                raise TimeUp()
        return cb

    def slsqp(z, maxiter=400):
        try:
            res = minimize(_obj, z, jac=_obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': 1e-13},
                           callback=make_cb())
            return _repair(res.x)
        except TimeUp:
            raise
        except Exception:
            return None

    # Polishing pass from start
    if time.process_time() < deadline:
        zr = slsqp(z_best.copy(), maxiter=1000)
        if zr is not None:
            val = float(np.sum(zr[2*N:3*N]))
            if val > best_val:
                best_val = val
                z_best = zr.copy()

    # Iterated local search: perturb one circle to largest empty spot, re-polish.
    rng = np.random.RandomState(987654321)
    stall = 0
    while time.process_time() < deadline:
        x, y, r = _unpack(z_best.copy())
        # Pick a circle to relocate. Bias toward medium-small ones and random.
        # Mix strategies across iterations.
        mode = rng.randint(3)
        if mode == 0:
            # smallest circle
            i = int(np.argmin(r))
        elif mode == 1:
            # random
            i = int(rng.randint(N))
        else:
            # random among those not touching many
            i = int(rng.randint(N))

        bx, by, bd = _largest_empty(x, y, r, i, G=40)
        if bd <= 1e-4:
            # Fall back to random point
            bx = rng.rand(); by = rng.rand()
            bd = 0.01

        z_try = z_best.copy()
        z_try[i] = bx
        z_try[N+i] = by
        z_try[2*N+i] = max(bd, 1e-4)
        z_try = _repair(z_try)

        # small random jitter on a couple circles to escape
        if rng.rand() < 0.5:
            k = int(rng.randint(N))
            z_try[k] += rng.randn() * 0.005
            z_try[N+k] += rng.randn() * 0.005
            z_try = _repair(z_try)

        try:
            zr = slsqp(z_try, maxiter=300)
        except TimeUp:
            break
        if zr is None:
            continue
        val = float(np.sum(zr[2*N:3*N]))
        if val > best_val + 1e-12:
            best_val = val
            z_best = zr.copy()
            stall = 0
        else:
            stall += 1

        # Occasionally re-polish current best to consolidate
        if stall >= 12 and time.process_time() < deadline:
            try:
                zr = slsqp(z_best.copy(), maxiter=500)
                if zr is not None:
                    val = float(np.sum(zr[2*N:3*N]))
                    if val > best_val:
                        best_val = val
                        z_best = zr.copy()
            except TimeUp:
                break
            stall = 0

    # Final polish
    if time.process_time() < deadline:
        try:
            zr = slsqp(z_best.copy(), maxiter=800)
            if zr is not None:
                val = float(np.sum(zr[2*N:3*N]))
                if val > best_val:
                    best_val = val
                    z_best = zr.copy()
        except TimeUp:
            pass

    x, y, r = _unpack(z_best)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    # Final safety: shrink to guarantee feasibility
    for _ in range(50):
        bad = False
        for i in range(N):
            if x[i] - r[i] < 0 or x[i] + r[i] > 1 or y[i] - r[i] < 0 or y[i] + r[i] > 1:
                r[i] *= 0.999
                bad = True
        for i in range(N):
            for j in range(i+1, N):
                d = np.hypot(x[i]-x[j], y[i]-y[j])
                if d < r[i] + r[j]:
                    ex = (r[i] + r[j] - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - ex, 1e-9)
                    r[j] = max(r[j] - ex, 1e-9)
                    bad = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not bad:
            break
    return np.column_stack([x, y, r])

