def _lp_radii(x, y):
    n = N
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i+1, n):
            d = np.hypot(x[i]-x[j], y[i]-y[j])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A_ub.append(row); b_ub.append(d)
    for i in range(n):
        row = np.zeros(n); row[i] = 1.0
        A_ub.append(row)
        b_ub.append(min(x[i], 1.0-x[i], y[i], 1.0-y[i]))
    A_ub = np.array(A_ub); b_ub = np.array(b_ub)
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=[(0.0, None)]*n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-9)
    except Exception:
        pass
    return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    cons = _build_cons()
    bounds = [(0.0, 1.0)] * (2*N) + [(1e-9, 0.5)] * N

