    def evaluate(z):
        zf = _repair(z)
        val = float(np.sum(zf[2*N:3*N]))
        if val > best[1]:
            best[1] = val
            best[0] = zf.copy()
        return val

    def solve(z_start, maxiter, ftol):
        if time.process_time() > deadline:
            return None
        def cb(z):
            if time.process_time() > deadline:
                raise TimeUp()
