            res = minimize(_obj, z_start, jac=_obj_jac, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': ftol},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    def polish(z):
        x, y, r = _unpack(z.copy())
        rlp = _lp_radii(x, y)
        if rlp is not None:
            z2 = _repair(np.concatenate([x, y, rlp]))
            evaluate(z2)
            res = solve(z2, 300, 1e-13)
            if res is not None:
                evaluate(res)
                return res
            return z2
        return z

    if start is not None:
        s = np.asarray(start, dtype=float)
        z_init = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5*(j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_init = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_init = _repair(z_init)
    evaluate(z_init)

    res0 = solve(z_init, 3000, 1e-13)
    if res0 is not None:
        evaluate(res0)
        polish(res0)

    rng = np.random.default_rng(2024)
    tries = 0
    while time.process_time() < deadline:
        tries += 1
        z = best[0].copy()
        frac = (time.process_time() - t0) / max(deadline - t0, 1e-9)
        scale = 1.0 - 0.6 * min(frac, 1.0)
        sx = rng.uniform(0.002, 0.02) * scale
        sr = rng.uniform(0.001, 0.006) * scale
        # perturb a random subset
        npert = rng.integers(2, 8)
        idx = rng.choice(N, size=npert, replace=False)
        z[0:N][idx] += rng.normal(0, sx, npert)
        z[N:2*N][idx] += rng.normal(0, sx, npert)
        z[2*N:3*N][idx] += rng.normal(0, sr, npert)
        z[0:N] = np.clip(z[0:N], 0.0, 1.0)
        z[N:2*N] = np.clip(z[N:2*N], 0.0, 1.0)
        z[2*N:3*N] = np.clip(z[2*N:3*N], 1e-6, 0.5)
