    x, y, r = _unpack(z)
    r = np.maximum(r - 1e-8, 1e-9)
    x = np.clip(x, r + 1e-9, 1.0 - r - 1e-9)
    y = np.clip(y, r + 1e-9, 1.0 - r - 1e-9)
    return np.column_stack([x, y, r])

