                        g[i] = 1.0; g[2 * N + i] = -1.0
                    elif kind == 1:
                        g[i] = -1.0; g[2 * N + i] = -1.0
                    elif kind == 2:
                        g[N + i] = 1.0; g[2 * N + i] = -1.0
                    else:
                        g[N + i] = -1.0; g[2 * N + i] = -1.0
                    return g
                return f, j
            f, j = make(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(N):
        for j in range(i + 1, N):
            def make(i, j):
                def f(z):
                    x, y, r = _unpack(z)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    return dx * dx + dy * dy - (r[i] + r[j]) ** 2

                def jac(z):
                    x, y, r = _unpack(z)
                    g = np.zeros(3 * N)
                    dx = x[i] - x[j]; dy = y[i] - y[j]
                    g[i] = 2 * dx; g[j] = -2 * dx
                    g[N + i] = 2 * dy; g[N + j] = -2 * dy
                    sr = 2 * (r[i] + r[j])
                    g[2 * N + i] = -sr; g[2 * N + j] = -sr
                    return g
                return f, jac
            f, jac = make(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': jac})
    return cons


def _obj(z):
    return -np.sum(z[2 * N:3 * N])


def _obj_jac(z):
    g = np.zeros(3 * N)
    g[2 * N:3 * N] = -1.0
    return g


class _TimeUp(Exception):
    pass


def _polish(z_start, deadline, bounds, cons, maxiter=2000, ftol=1e-14):
    def cb(zz):
        if time.process_time() > deadline:
            raise _TimeUp()

    try:
        res = minimize(_obj, z_start.copy(), jac=_obj_jac, method='SLSQP',
                       constraints=cons, bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': ftol},
                       callback=cb)
        zr = _repair(res.x)
        return zr, float(np.sum(zr[2 * N:3 * N]))
    except Exception:
        return z_start.copy(), float(np.sum(z_start[2 * N:3 * N]))


def _finalize(z):
    x, y, r = _unpack(z)
    r = np.maximum(r - 1e-11, 1e-11)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    # push apart any remaining overlap by shrinking
    for _ in range(200):
        changed = False
        for i in range(N):
            for j in range(i + 1, N):
                d = np.hypot(x[i] - x[j], y[i] - y[j])
                s = r[i] + r[j]
                if d < s:
                    ex = (s - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - ex, 1e-11)
                    r[j] = max(r[j] - ex, 1e-11)
                    changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    return np.column_stack([x, y, r])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.8

    if start is not None:
        s = np.asarray(start, dtype=float)
        z_best = np.concatenate([s[:, 0], s[:, 1], s[:, 2]])
    else:
        k = 6
        pts = [((i + 0.5 + 0.5 * (j % 2)) / k, (j + 0.5) / k)
               for j in range(k) for i in range(k)][:N]
        z_best = np.concatenate([np.array([p[0] for p in pts]),
                                 np.array([p[1] for p in pts]),
                                 np.full(N, 0.05)])
    z_best = _repair(z_best)
    best_val = float(np.sum(z_best[2 * N:3 * N]))

    bounds = [(0.0, 1.0)] * (2 * N) + [(1e-9, 0.5)] * N
    cons = _build_cons()

    # Phase 1: strong SLSQP polish from start.
    zr, val = _polish(z_best, deadline, bounds, cons, maxiter=3000)
    if val > best_val:
        best_val = val
        z_best = zr

    # Phase 2: penalty escalation for diversification.
    z = z_best.copy()
    P = 1e3
    while P <= 1e10 and time.process_time() < deadline - 3.0:
        try:
            res = minimize(lambda zz: _penalty_grad(zz, P), z, jac=True,
                           method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 200, 'ftol': 1e-15, 'gtol': 1e-13})
            z = res.x
        except Exception:
            break
        zr = _repair(z)
        val = float(np.sum(zr[2 * N:3 * N]))
        if val > best_val + 1e-10:
            zr2, val2 = _polish(zr, deadline, bounds, cons, maxiter=400)
            if val2 > best_val:
                best_val = val2
                z_best = zr2
            elif val > best_val:
                best_val = val
                z_best = zr.copy()
        P *= 10.0

    # Phase 3: local SLSQP polish of best to squeeze extra.
    zr, val = _polish(z_best, deadline, bounds, cons, maxiter=2000, ftol=1e-15)
    if val > best_val:
        best_val = val
        z_best = zr

    return _finalize(z_best)
